INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','easy','flashcard','What are the three layers of the glomerular filtration barrier, from blood to Bowman''s space?','["(1) Fenestrated capillary endothelium (pores 70-100 nm, prevents cellular elements); (2) Glomerular basement membrane (GBM — type IV collagen + heparan sulphate, charge selective, ~330 nm thick); (3) Podocyte foot processes with slit diaphragms (nephrin/podocin, size selective, final barrier). Together they allow free filtration of water and small solutes while retaining cells and large proteins."]','A','Three-layer barrier: endothelium (size), GBM (charge+size), slit diaphragm (size). Each layer adds selectivity; disruption causes proteinuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','easy','flashcard','What is the difference between cortical and juxtamedullary nephrons?','["Cortical nephrons (~85%): glomeruli in outer cortex, short loops of Henle that barely enter the medulla, supplied by peritubular capillaries. Juxtamedullary nephrons (~15%): glomeruli near the corticomedullary junction, LONG loops of Henle penetrating into the inner medulla, supplied by vasa recta. Juxtamedullary nephrons are essential for creating the medullary concentration gradient."]','A','Juxtamedullary nephrons (15%) have long loops and vasa recta — critical for building the medullary osmotic gradient; cortical nephrons (85%) have short loops.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','What are the three components of the juxtaglomerular apparatus (JGA) and their functions?','["(1) Macula densa — specialised cells in the early distal tubule sensing luminal NaCl concentration; mediates tubuloglomerular feedback. (2) Juxtaglomerular (granular) cells — modified smooth muscle cells in the afferent arteriole wall; secrete renin in response to low pressure, low NaCl, or beta-1 stimulation. (3) Extraglomerular mesangial (lacis) cells — communication/signalling role between macula densa and JG cells. Together these regulate GFR and systemic blood pressure via RAAS."]','A','JGA = macula densa (NaCl sensor) + JG cells (renin release) + lacis cells (signalling). Integrates TGF and RAAS for GFR and BP control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','What protein forms the slit diaphragm of podocytes, and what disease results from its loss-of-function mutation?','["Nephrin (encoded by NPHS1) is the key structural protein of the slit diaphragm, forming a zipper-like structure across the filtration slit. Loss-of-function mutations in NPHS1 cause congenital nephrotic syndrome of the Finnish type — massive proteinuria from birth due to failure of size-selective filtration. Podocin (NPHS2) anchors nephrin to the membrane; its mutations cause autosomal recessive focal segmental glomerulosclerosis (FSGS)."]','A','Nephrin (NPHS1) = slit diaphragm scaffold; mutations → congenital Finnish nephrotic syndrome. Podocin (NPHS2) mutations → FSGS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','What is the function of the vasa recta in the renal medulla?','["The vasa recta are hairpin capillary loops running parallel to juxtamedullary loops of Henle. They function as countercurrent exchangers: as blood descends, it equilibrates with the hyperosmotic interstitium (gaining solutes, losing water); as blood ascends, it returns solutes to the interstitium. This prevents washout of the medullary osmotic gradient while still supplying oxygen and nutrients. They also carry away water reabsorbed from collecting ducts."]','A','Vasa recta = countercurrent exchangers that preserve the medullary osmotic gradient while supplying blood. Increased flow washes out the gradient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','What is the role of mesangial cells within the glomerulus?','["Mesangial cells (modified pericytes) within the glomerulus: (1) Structural support for glomerular capillary loops; (2) Phagocytosis of trapped macromolecules and immune complexes; (3) Contraction in response to angiotensin II, vasopressin, and endothelin, reducing filtration surface area and GFR; (4) Relaxation in response to ANP and dopamine; (5) Cytokine and growth factor secretion in inflammation; (6) Proliferation in diabetic nephropathy and IgA nephropathy."]','A','Mesangial cells: structural support, phagocytosis, contraction (Ang II → reduced GFR), proliferation in disease. Key targets in glomerular pathology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','How many segments does the renal tubule have, and what are they in order from glomerulus to collecting duct?','["The renal tubule segments in order: (1) Proximal convoluted tubule (PCT); (2) Proximal straight tubule (pars recta); (3) Descending thin limb of loop of Henle; (4) Ascending thin limb (juxtamedullary nephrons only); (5) Thick ascending limb (TAL); (6) Distal convoluted tubule (DCT); (7) Connecting tubule; (8) Cortical collecting duct; (9) Outer medullary collecting duct; (10) Inner medullary collecting duct (IMCD). The loop of Henle includes segments 3-5."]','A','10 segments: PCT → pars recta → descending thin → ascending thin → TAL → DCT → connecting tubule → cortical CD → outer medullary CD → IMCD.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','medium','flashcard','What gives the proximal convoluted tubule its distinctive histological appearance, and what does it reflect functionally?','["PCT cells have a prominent brush border (microvilli) on their apical surface, increasing luminal surface area ~20-fold. They also have abundant mitochondria basally to power Na-K-ATPase. Histologically: tall cuboidal cells with eosinophilic (pink) cytoplasm, brush border visible on H&E. This architecture reflects the PCT''''s function of reabsorbing ~65% of filtered sodium, water, glucose, amino acids, and bicarbonate — the most metabolically active tubular segment."]','A','PCT brush border (microvilli) + basal mitochondria = high-capacity reabsorptive cell. Reabsorbs ~65% of filtered load. Brush border lost early in ischaemic AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','hard','flashcard','Explain the charge-selective and size-selective barriers of the glomerular filtration barrier and how they are altered in nephrotic syndrome.','["SIZE selectivity: The slit diaphragm (nephrin/podocin) prevents passage of molecules >70 kDa. The GBM pore size (~8 nm effective radius) limits passage of large proteins. CHARGE selectivity: Heparan sulphate proteoglycans in the GBM carry negative charges that repel negatively charged proteins like albumin (MW 69 kDa, negative at physiological pH). In nephrotic syndrome: podocyte foot process effacement disrupts slit diaphragms (size barrier lost) and heparan sulphate loss reduces charge barrier. Both allow massive albumin leakage (>3.5 g/day)."]','A','Dual barrier: size (slit diaphragm, GBM pore size) + charge (heparan sulphate repels albumin). Nephrotic syndrome loses both → massive albuminuria >3.5 g/day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Anatomy','hard','flashcard','What is the renal cortex:medulla blood flow ratio, and why is the medulla vulnerable to ischaemia despite receiving blood?','["Cortex receives ~90-95% of total renal blood flow (~800 mL/100g/min) — one of the highest flow rates in the body. Medulla receives only ~5-10% (~30-40 mL/100g/min) via vasa recta. The medulla is metabolically active (thick ascending limb has high Na-K-ATPase activity) yet poorly perfused. Additionally, the medulla has a low pO2 (~10-15 mmHg at papilla) because countercurrent exchange causes O2 shunting. This makes the outer medulla — particularly the TAL — the most vulnerable segment to ischaemic injury in AKI."]','A','Cortex 90-95% vs medulla 5-10% of RBF. TAL is metabolically avid but poorly oxygenated (O2 shunting via countercurrent) → most vulnerable to AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','easy','flashcard','State the Starling forces governing glomerular filtration and their normal values.','["Four Starling forces at the glomerulus: FAVOURING filtration: (1) Glomerular capillary hydrostatic pressure (PGC) = ~60 mmHg; (2) Bowman''''s space oncotic pressure (πBS) ≈ 0 mmHg (no protein normally). OPPOSING filtration: (3) Bowman''''s space hydrostatic pressure (PBS) ≈ 18 mmHg; (4) Glomerular capillary oncotic pressure (πGC) ≈ 32 mmHg. Net filtration pressure = 60 − 18 − 32 = +10 mmHg. GFR = Kf × net filtration pressure = 12.5 × 10 = 125 mL/min."]','A','NFP = PGC − PBS − πGC = 60 − 18 − 32 = 10 mmHg. GFR = Kf × NFP = 125 mL/min. Bowman space oncotic = 0 (no protein in filtrate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','easy','flashcard','What is the filtration fraction and what is its normal value?','["Filtration fraction (FF) = GFR / Renal Plasma Flow (RPF) = 125 mL/min / 625 mL/min = 0.20 (20%). This means 20% of the plasma entering the glomerulus is filtered into Bowman''''s space; 80% passes on to the efferent arteriole and peritubular capillaries. Increased FF raises peritubular capillary oncotic pressure, enhancing tubular reabsorption. Angiotensin II preferentially constricting the efferent arteriole raises FF."]','A','FF = GFR/RPF = 125/625 = 20%. Raised FF (e.g., by Ang II efferent constriction) increases peritubular oncotic pressure, enhancing tubular Na+ reabsorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','Describe the myogenic mechanism of renal autoregulation.','["The myogenic mechanism is intrinsic to afferent arteriole smooth muscle. When renal perfusion pressure rises, the vessel wall is stretched → voltage-gated Ca2+ channels open → Ca2+ influx → smooth muscle contraction → afferent arteriole constriction → resistance increases → GFR remains stable. Conversely, decreased pressure → reduced stretch → relaxation → vasodilation → maintained GFR. This mechanism acts within seconds and maintains GFR over MAP 75-160 mmHg. It is independent of neural or hormonal control."]','A','Myogenic reflex: stretch → VGCC open → Ca2+ → contraction → normalises GFR. Acts within seconds. Maintains autoregulation MAP 75-160 mmHg. Independent of nerves/hormones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','How does constriction of the efferent arteriole affect GFR and renal blood flow?','["Efferent constriction (e.g., by angiotensin II): INCREASES glomerular hydrostatic pressure (blood ''''backs up'''' into glomerulus) → increases GFR. DECREASES renal blood flow (increased resistance downstream). Net effect: GFR/RBF ratio increases (higher filtration fraction). This is how the kidney maintains GFR during hypoperfusion. However, severe efferent constriction eventually reduces RBF so much that GFR falls despite high filtration fraction (ischaemia)."]','A','Efferent constriction (Ang II): raises PGC → increases GFR but decreases RBF → higher FF. Maintains GFR in hypoperfusion; severe constriction → ischaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','What is tubuloglomerular feedback (TGF) and what mediates it?','["TGF is a negative feedback mechanism: increased GFR → more NaCl delivered to macula densa → macula densa releases ATP (→ adenosine) and possibly PGE2 → adenosine binds A1 receptors on afferent arteriole → vasoconstriction → GFR returns to normal. Mediators: ATP, adenosine (main signal), thromboxane A2. Macula densa also secretes nitric oxide (counterbalancing vasodilator). TGF operates within seconds and complements the myogenic mechanism to form the full autoregulatory response."]','A','TGF: high NaCl at macula densa → adenosine (via ATP) → afferent constriction → GFR. Complements myogenic reflex. Adenosine A1 receptor is the key effector.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','How does severe hypoalbuminaemia affect GFR, and why do nephrotic patients not typically become anuric?','["Hypoalbuminaemia reduces plasma oncotic pressure (normally 32 mmHg opposing filtration). Lower oncotic pressure → reduced force opposing filtration → net filtration pressure increases → GFR transiently rises. However, increased GFR raises oncotic pressure in efferent blood (more protein-free fluid filtered, leaving more protein per unit volume), which then enhances peritubular reabsorption. Additionally, interstitial oedema and volume contraction activate RAAS, tending to normalise GFR. Nephrotic patients typically maintain adequate GFR until late-stage disease."]','A','Low albumin → lower πGC → initially higher NFP/GFR. Efferent protein concentration rise re-establishes equilibrium. RAAS activation normalises GFR. Anuria unusual until late.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','What is the Kf (filtration coefficient) and what factors reduce it?','["Kf = hydraulic conductivity (Lp) × filtration surface area (S). Normal glomerular Kf ≈ 12.5 mL/min/mmHg (far higher than other capillary beds). Factors reducing Kf: (1) Mesangial cell contraction (angiotensin II, vasopressin, endothelin) — reduces effective filtration surface area; (2) Glomerular disease (diabetic nephropathy, GN) — reduces Lp by thickening or scarring the GBM; (3) NSAID use — reduces prostaglandin-mediated vasodilation affecting capillary surface area. Reduced Kf directly lowers GFR."]','A','Kf = Lp × S = 12.5 mL/min/mmHg. Reduced by: mesangial contraction (Ang II), GBM scarring (DM, GN), NSAIDs. Direct determinant of GFR alongside NFP.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','medium','flashcard','How does increased sympathetic activity affect GFR and renal blood flow?','["Sympathetic stimulation causes alpha-1 adrenoceptor-mediated constriction of BOTH afferent and efferent arterioles. Net effect: preferential afferent constriction → both RBF and GFR fall. However, because efferent arterioles are also constricted, the fall in GFR is less than the fall in RBF. Simultaneously, renin release (beta-1 stimulation of JG cells) activates RAAS, causing Na+ retention. Severe sympathetic activation (haemorrhage, heart failure) can nearly abolish GFR to redirect blood flow to vital organs."]','A','Sympathetic (α1): both afferent+efferent constriction, predominantly afferent → RBF↓↓ GFR↓. β1 stimulation → renin → RAAS → Na retention. Severe activation nearly abolishes GFR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','hard','flashcard','Why can GFR initially be maintained in conditions that reduce renal plasma flow, and what eventually causes it to fall?','["With reduced RPF, autoregulation (myogenic + TGF) dilates the afferent arteriole to maintain glomerular pressure. Additionally, angiotensin II preferentially constricts the efferent arteriole (maintaining glomerular pressure despite low flow). This preserves GFR at the expense of increased filtration fraction and reduced peritubular capillary hydrostatic pressure (enhancing reabsorption). GFR eventually falls when: (1) autoregulation is overwhelmed (MAP < 75 mmHg); (2) severe RBF reduction means even maximum efferent constriction cannot maintain glomerular pressure; (3) ischaemia injures the tubules."]','A','GFR maintained by: afferent dilation (autoregulation) + efferent constriction (Ang II). Falls when MAP <75 mmHg overwhelms autoregulation or ischaemia injures tubules.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','GFR & Filtration','hard','flashcard','What is the significance of glomerular capillary oncotic pressure rising along the length of the glomerular capillary, and how does this affect filtration?','["As plasma is filtered along the glomerular capillary, protein-free filtrate leaves but proteins remain. This concentrates plasma proteins, progressively raising capillary oncotic pressure from ~25 mmHg at the afferent end to ~35 mmHg at the efferent end. In some species (rats with high GFR), oncotic pressure rises to equal glomerular hydrostatic pressure by the efferent end (filtration equilibrium), meaning the last portion of the capillary contributes nothing to filtration. Humans likely operate near but not quite at filtration equilibrium under normal conditions. Any factor reducing RPF shifts the system toward earlier equilibrium, reducing total GFR."]','A','Oncotic pressure rises along glomerular capillary (protein concentrates as filtrate leaves) → approaches filtration equilibrium. Low RPF → earlier equilibrium → lower GFR even with normal pressures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','easy','flashcard','What percentage of filtered glucose is normally reabsorbed in the proximal tubule, and at what plasma glucose does glucosuria begin?','["100% of filtered glucose is normally reabsorbed by the proximal tubule (via SGLT2 in early PCT and SGLT1 in late PCT). Glucosuria begins when plasma glucose exceeds ~180 mg/dL — the renal threshold — at which point the filtered load (~225 mg/min) begins to exceed the transport maximum (Tm ~375 mg/min in average patients). Due to splay, some nephrons begin spilling glucose even below 180 mg/dL. In diabetes, glucosuria is a clinical sign of poorly controlled blood glucose."]','A','100% glucose reabsorbed normally (SGLT2 early PCT, SGLT1 late PCT). Glucosuria threshold ~180 mg/dL (Tm ~375 mg/min). Splay causes inter-nephron variation. Key in DM monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','easy','flashcard','What drives sodium reabsorption in the proximal tubule at the cellular level?','["Na+ reabsorption in the PCT is driven by the sodium electrochemical gradient established by basolateral Na-K-ATPase (which pumps 3 Na+ out and 2 K+ in, keeping intracellular Na+ low ~12 mEq/L vs luminal 140 mEq/L). Apical entry: via NHE3 (Na-H exchanger, coupled to H+ secretion), SGLT1/2 (with glucose), Na-amino acid cotransporters, and Na-phosphate cotransporters. Exit: basolaterally via Na-K-ATPase (active) and Na-HCO3- cotransporter (NBC1). Water follows osmotically via AQP1 (apical and basolateral)."]','A','Basolateral Na-K-ATPase sets low intracellular Na+ → drives apical Na+ entry via NHE3, SGLT1/2, cotransporters. Water follows via AQP1. Classic secondary active transport.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','Describe the mechanism of bicarbonate reabsorption in the proximal convoluted tubule.','["The PCT reabsorbs ~80% of filtered HCO3- INDIRECTLY: Step 1: NHE3 secretes H+ into lumen; Step 2: H+ + HCO3- (filtered) → H2CO3; Step 3: Luminal carbonic anhydrase IV: H2CO3 → CO2 + H2O; Step 4: CO2 diffuses into PCT cell; Step 5: Intracellular CA II: CO2 + H2O → H2CO3 → H+ + HCO3-; Step 6: H+ secreted again (cycle); HCO3- exits basolaterally via NBC1 (Na-HCO3- cotransporter) into blood. Net result: filtered HCO3- ''''reabsorbed'''' without direct HCO3- transport. Acetazolamide blocks CA II and IV, impairing this process."]','A','PCT reabsorbs 80% HCO3- indirectly: NHE3 secretes H+ → luminal H+ + HCO3- → CO2 (CA IV) → diffuses in → CA II regenerates HCO3- → exits via NBC1. Acetazolamide blocks this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','What is Fanconi syndrome and what are its cardinal features?','["Fanconi syndrome is a generalised dysfunction of PCT reabsorption, causing urinary ''''wasting'''' of normally reabsorbed substances despite normal plasma levels. Cardinal features: glucosuria (normoglycaemic), phosphaturia (hypophosphataemia → rickets/osteomalacia), aminoaciduria (all amino acids), bicarbonaturia (type 2 proximal RTA), uricosuria (hypouricaemia), potassium wasting, and low-molecular-weight proteinuria. Causes: Wilson''''s disease, galactosaemia, fructose intolerance, cystinosis, multiple myeloma, tenofovir toxicity, and heavy metals (lead, mercury, cadmium)."]','A','Fanconi = generalised PCT failure → glucose, phosphate, amino acids, HCO3-, urate all wasted. Causes: cystinosis, Wilson''''s, tenofovir, heavy metals. Type 2 (proximal) RTA component.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','How does parathyroid hormone (PTH) affect phosphate reabsorption in the proximal tubule?','["PTH acts on PTH/PTHrP receptors (Gs-coupled) on the basolateral membrane of PCT cells → cAMP → PKA → phosphorylation and internalisation of NaPi-IIa and NaPi-IIc sodium-phosphate cotransporters from the apical membrane into lysosomes for degradation. Result: marked reduction in phosphate reabsorption → phosphaturia → lower plasma phosphate. This is the primary mechanism of PTH-induced phosphaturia. FGF23 acts similarly via FGFR1/Klotho. Phosphaturia in hyperparathyroidism is a key diagnostic clue."]','A','PTH → cAMP → PKA → internalises apical NaPi-IIa/IIc → phosphaturia + hypophosphataemia. FGF23 acts similarly. Key: phosphaturia differentiates primary from familial hypercalcaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','How are organic anions (e.g., PAH, penicillin, urate) secreted into the proximal tubule lumen?','["Two-step process: Step 1 (basolateral uptake): OAT1 and OAT3 (organic anion transporters) on basolateral membrane exchange intracellular alpha-ketoglutarate for extracellular organic anions; alpha-ketoglutarate gradient maintained by dicarboxylate cotransporter NaDC3 (secondary active transport driven by Na+ gradient; ultimately driven by Na-K-ATPase — tertiary active transport). Step 2 (apical secretion): MRP2 (multidrug resistance protein 2) and OAT4/URAT1 on apical membrane export anions into the lumen. Clinical relevance: probenecid blocks OAT1/3, reducing penicillin secretion (probenecid extends penicillin half-life) and reducing urate secretion."]','A','Organic anion secretion: basolateral OAT1/3 (tertiary active, α-KG exchange) → apical MRP2/OAT4 export. Probenecid blocks OAT1/3 → extends penicillin t½ and reduces urate secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','What is the transport maximum (Tm) for glucose reabsorption and how is it measured?','["Tm for glucose ≈ 375 mg/min in males (slightly lower in females). It is measured by glucose titration: progressively increasing plasma glucose while measuring filtered load (GFR × plasma glucose) and urinary glucose excretion. When urinary glucose excretion = filtered load − Tm, the Tm has been reached. At the point where the titration curve plateaus, Tm = filtered load − excreted glucose. The practical ''''renal threshold'''' (~180 mg/dL plasma glucose) is lower than the theoretical threshold due to nephron heterogeneity causing the ''''splay'''' in the titration curve."]','A','Glucose Tm ≈ 375 mg/min measured by titration curve. Practical threshold 180 mg/dL lower than theoretical due to splay (nephron heterogeneity). SGLT2 inhibitors exploit this mechanism.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','medium','flashcard','How does the PCT handle amino acids, and what happens when a single amino acid transporter is mutated?','["PCT reabsorbs nearly 100% of filtered amino acids via Na-dependent cotransporters (different transporters for neutral, acidic, and basic amino acids) on the apical membrane. Exit is via facilitated transporters on the basolateral membrane. When a specific transporter mutates: Hartnup disease: neutral amino acid transporter (B0AT1/SLC6A19) loss → tryptophan and other neutral amino acid wasting → pellagra-like rash, ataxia, psychiatric features (from niacin deficiency). Cystinuria: cationic amino acid transporter (SLC3A1/SLC7A9) loss → cystine, ornithine, lysine, arginine wasting → cystine kidney stones."]','A','PCT reabsorbs 100% of amino acids via Na-cotransporters. Hartnup (B0AT1 loss) → tryptophan wasting → pellagra. Cystinuria (SLC3A1/7A9) → COLA wasting → cystine stones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','hard','flashcard','Explain the isosmotic nature of PCT reabsorption and why it is important.','["PCT reabsorption is ISOSMOTIC: water follows NaCl and solute reabsorption via osmosis through AQP1 (apical and basolateral), keeping luminal osmolality equal to plasma (~300 mOsm/kg) throughout the PCT despite ~65% volume reduction. Mechanism: Na+ and solute reabsorption creates a slight osmotic gradient across the epithelium; water crosses rapidly via AQP1 (high water permeability). Importance: (1) maintains constant tubular fluid concentration, allowing concentration-dependent transporters to function optimally; (2) prevents excessive tubular cell shrinkage; (3) large volume reabsorption (120 mL/min of 125 mL/min filtered) occurs without concentration changes, passing to the loop where concentration work occurs."]','A','PCT reabsorption is isosmotic (300 mOsm throughout). AQP1 high permeability allows ~65% volume removal without osmotic change. Sets up loop of Henle for concentration work.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Proximal Tubule Function','hard','flashcard','SGLT2 inhibitors (gliflozins) cause glucosuria and are used in diabetes and heart failure. What are the renal physiological consequences beyond glucosuria?','["SGLT2 inhibition (early PCT) effects: (1) Glucosuria → osmotic diuresis → increased tubular flow to macula densa; (2) Increased NaCl delivery to macula densa → TGF → afferent arteriole constriction → reduced GFR (desired in diabetic nephropathy — reduces glomerular hypertension); (3) Natriuresis (Na co-transported with glucose) → volume reduction → reduced preload/afterload (heart failure benefit); (4) Increased ammoniagenesis due to mild metabolic acidosis (SGLT2 inhibitors cause mild DKA risk); (5) Reduced proximal tubular O2 consumption (less active transport). These pleiotropic effects explain cardio-renal benefits beyond glucose lowering."]','A','SGLT2i pleiotropic effects: osmotic diuresis → TGF → afferent constriction → reduced glomerular hypertension; natriuresis → preload↓; reduced PCT O2 consumption. Explains cardio-renal protection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','easy','flashcard','What are the water and solute permeability properties of each segment of the loop of Henle?','["(1) Descending thin limb: HIGH water permeability (AQP1), LOW NaCl permeability, low urea permeability → fluid concentrates as water leaves. (2) Ascending thin limb (inner medulla): NO water permeability, HIGH NaCl permeability (passive efflux) → NaCl diffuses out. (3) Thick ascending limb (outer medulla): NO water permeability (no AQP), active NaCl reabsorption via NKCC2 → tubular fluid diluted, interstitium concentrated. Net result: fluid entering the loop at 300 mOsm/kg reaches 1200 mOsm/kg at the tip, then returns diluted to 100 mOsm/kg at the TAL exit."]','A','Descending limb: water permeable (AQP1), NaCl impermeable → concentrates. Ascending thin: NaCl permeable, water impermeable → dilutes. TAL: active NaCl pump (NKCC2), water impermeable → dilutes further.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','easy','flashcard','What is the mechanism of action of loop diuretics (furosemide), and why are they the most potent diuretics?','["Loop diuretics (furosemide, bumetanide, torsemide, ethacrynic acid) competitively block the NKCC2 (Na-K-2Cl) cotransporter on the apical membrane of TAL cells. Without NaCl reabsorption in the TAL: (1) the medullary osmotic gradient is not built → ADH cannot concentrate urine regardless of level → maximum urine output even with high ADH; (2) ~25% of filtered NaCl that normally reabsorbs in the TAL is lost → profound natriuresis; (3) increased distal K+ delivery with RAAS activation → significant hypokalaemia. No other diuretic affects this much of the filtered Na+ load."]','A','Furosemide blocks NKCC2 → destroys medullary gradient → ADH ineffective → dilute urine. Handles 25% filtered Na+ → most potent diuretics. Adverse: hypokalaemia, hypomagnesaemia, ototoxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','Explain the countercurrent multiplier mechanism of the loop of Henle step by step.','["The countercurrent multiplier builds the medullary gradient: Step 1: TAL actively pumps NaCl into interstitium (single effect: ~200 mOsm/kg gradient between lumen and interstitium). Step 2: Water flows out of descending limb (water permeable) into the now slightly hyperosmotic interstitium. Step 3: Fluid at the loop tip is highly concentrated (~1200 mOsm/kg). Step 4: In the ascending limb, NaCl is pumped out (water cannot follow — impermeable). Step 5: Dilute fluid (~100-150 mOsm/kg) exits into the DCT. Step 6: The hairpin configuration allows the small single-effect gradient (200 mOsm) to be multiplied longitudinally into a large gradient (300→1200 mOsm/kg). Urea recycling contributes ~50% of the papillary gradient."]','A','Countercurrent multiplier: TAL NaCl pump (single effect 200 mOsm) → water exits descending limb → amplified along hairpin → 1200 mOsm at tip. Urea recycling adds ~50% of gradient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','How does urea recycling contribute to the medullary osmotic gradient?','["Urea recycling: (1) In the collecting duct, water is reabsorbed (via AQP2 in the presence of ADH), concentrating urea in the lumen. (2) ADH upregulates UT-A1 and UT-A3 urea transporters in the IMCD → concentrated urea diffuses into inner medullary interstitium. (3) Urea enters the descending thin limb of juxtamedullary nephrons via UT-A2 → carried up the ascending limb → reabsorbed again in TAL → returns to IMCD. This recycling amplifies inner medullary osmolality. Urea contributes ~500-600 mOsm/kg of the ~1200 mOsm/kg papillary gradient (half). Protein malnutrition reduces urea recycling and impairs concentrating ability."]','A','Urea recycling: ADH → UT-A1/A3 in IMCD allows urea exit into inner medulla → enters descending limb (UT-A2) → recycled. Urea = ~500 mOsm/kg of 1200 gradient. Low protein → impaired concentration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','What is the ''''single effect'''' of the countercurrent multiplier, and how is it amplified?','["The ''''single effect'''' is the osmotic gradient (~200 mOsm/kg) established at any ONE horizontal level between the TAL (which actively pumps NaCl without water) and the adjacent interstitium/descending limb. This is a relatively modest gradient. Amplification occurs because of the COUNTERCURRENT (opposite flow) arrangement: as more fluid flows through the system, each horizontal level re-establishes its 200 mOsm gradient, and the overall effect accumulates longitudinally along the axis of the loop. The longer the loop (juxtamedullary nephrons), the greater the corticomedullary gradient that can be achieved."]','A','Single effect = 200 mOsm gradient at each level due to TAL NaCl pumping. Countercurrent flow amplifies this modest gradient longitudinally → 1200 mOsm at tip. Longer loop = larger gradient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','What are the permeability characteristics that make the thick ascending limb (TAL) uniquely suited for building the medullary gradient?','["TAL features: (1) WATER IMPERMEABLE — no aquaporins expressed (despite neighbouring segments having AQP1); NaCl reabsorption is not accompanied by water → concentrating effect. (2) ACTIVE NaCl reabsorption via apical NKCC2 (abundant mitochondria to power Na-K-ATPase); NaCl extracted without water → dilutes luminal fluid AND concentrates interstitium. (3) HIGH transport rate — the TAL handles ~25% of filtered NaCl. (4) Paracellular Ca2+ and Mg2+ reabsorption via claudin-16/19 driven by lumen-positive potential from K+ recycling via ROMK. Loss of NKCC2 (Bartter type I) or furosemide completely abolishes gradient building."]','A','TAL is water-impermeable (no AQP) + actively pumps NaCl via NKCC2 → dilutes lumen AND concentrates medulla. Also drives paracellular Ca2+/Mg2+ reabsorption via lumen-positive potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','How do the vasa recta act as countercurrent exchangers to preserve the medullary gradient?','["Vasa recta mechanism: As blood descends into the medulla, it encounters progressively higher osmolality. Water leaves (via aquaporins in endothelial cells) and NaCl/urea enter the blood passively → blood becomes hyperosmotic. As blood ascends, the reverse occurs: water re-enters and solutes leave back into the interstitium. Net result: the same solutes are ''''recycled'''' within the medullary region rather than being carried away. Critically, only slow blood flow through the vasa recta allows equilibration time; rapid flow would wash the gradient away. High medullary blood flow (e.g., from ANP or prostaglandins) can dilute the gradient."]','A','Vasa recta countercurrent exchange: solutes enter descending blood, return to interstitium on ascending → recycles gradient rather than washing it away. Slow flow essential; high flow (ANP, PGs) dilutes gradient.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','medium','flashcard','What are the clinical features of Bartter syndrome and how do they differ between type I and type II?','["Bartter syndrome features (all types): salt wasting, hypokalaemia, metabolic alkalosis, hyperreninaemia without hypertension, hypercalciuria (distinguishing from Gitelman). Type I (NKCC2 loss): severe, neonatal onset, severe salt wasting, polyhydramnios. Type II (ROMK loss): also severe neonatal onset; paradoxically may have transient hyperkalaemia at birth (ROMK needed for K+ recycling to drive NKCC2) before developing hypokalaemia. Type III (ClC-Kb loss): milder, childhood onset. All mimic chronic furosemide use because they disrupt TAL function."]','A','Bartter: salt wasting, hypokalaemia, alkalosis, hyperreninaemia, hypercalciuria = chronic furosemide picture. Type I (NKCC2): severe neonatal. Type II (ROMK): transient HYPERkalaemia then hypokalaemia. Type III: milder.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','hard','flashcard','Why does prolonged furosemide use reduce the medullary concentration gradient, and how long does it take to recover after stopping?','["Furosemide blocks NKCC2 → no NaCl accumulation in medullary interstitium → gradient falls from 1200 toward 300 mOsm/kg (isotonic). Recovery after stopping: requires re-establishment of the gradient via repeated cycles of TAL NaCl pumping AND urea recycling in the IMCD. Urea accumulation is particularly slow as it depends on concentrating multiple passes of tubular fluid. Full recovery takes ~12-24 hours in normal kidneys. During recovery, even if ADH is high, concentrating ability is impaired (''''post-diuretic hyposthenuria''''). This is clinically important: patients stopping furosemide may temporarily be unable to concentrate urine maximally."]','A','Furosemide destroys medullary gradient → gradient recovery takes 12-24 h after stopping. During recovery: high ADH cannot concentrate urine (gradient absent). Urea recycling reconstitution is slowest step.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Loop of Henle & Countercurrent','hard','flashcard','Explain why inner medullary urea concentration can reach ~600 mOsm/kg despite urea being lipid-soluble and theoretically able to equilibrate everywhere.','["Urea appears lipid-soluble but its membrane permeability is low WITHOUT urea transporters. Different segments have different urea permeability: TAL, DCT, cortical and outer medullary collecting ducts are relatively impermeable to urea (low UT expression). The IMCD has ADH-regulated UT-A1/A3 → urea selectively accumulates in the IMCD lumen (concentrated by water removal) and exits ONLY into the inner medullary interstitium. This segment-specific permeability pattern allows urea to be ''''trapped'''' and concentrated in the inner medulla. Without ADH (or UT-A1/A3 blockade), urea equilibrates across all segments → inner medullary urea accumulation fails → concentrating ability halved."]','A','Urea accumulates despite lipid solubility because UT expression is segment-specific. IMCD UT-A1/A3 (ADH-regulated) allows selective urea exit into inner medulla. Proximal segments UT-poor → urea trapped. ADH doubles inner medullary urea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','easy','flashcard','What are the two main cell types in the collecting duct and their primary functions?','["(1) Principal cells (~65-70% of collecting duct cells): Reabsorb Na+ (via apical ENaC), secrete K+ (via apical ROMK), and reabsorb water (via AQP2 in response to ADH and AQP3/4 basolaterally). Regulated by aldosterone (upregulates ENaC and Na-K-ATPase) and ADH (inserts AQP2). (2) Intercalated cells (~30-35%): Alpha-intercalated cells secrete H+ (H+-ATPase apical, AE1 basolateral HCO3- exit) — active in acidosis. Beta-intercalated cells secrete HCO3- (pendrin apical Cl-/HCO3- exchanger) — active in alkalosis."]','A','Principal cells (65-70%): ENaC Na+ in, ROMK K+ out, AQP2 water in. Regulated by aldosterone and ADH. Intercalated cells (30-35%): alpha = H+ secretion; beta = HCO3- secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','easy','flashcard','How does aldosterone increase sodium reabsorption and potassium secretion in principal cells?','["Aldosterone pathway: Aldosterone (lipid-soluble) enters principal cells → binds mineralocorticoid receptor (MR) in cytoplasm → receptor-hormone complex translocates to nucleus → stimulates transcription of: (1) SGK1 (serum and glucocorticoid-regulated kinase 1) → phosphorylates Nedd4-2, preventing ENaC ubiquitination/degradation → more ENaC on apical membrane; (2) Na-K-ATPase subunits → more basolateral pump activity → greater Na+ exit. Net: more luminal negativity → more K+ secretion via ROMK. Actions take 30-90 min (genomic) but some rapid non-genomic effects also exist."]','A','Aldosterone → MR → nucleus → SGK1 (stabilises ENaC via Nedd4-2 phosphorylation) + Na-K-ATPase↑ → more Na+ in, more lumen negativity → K+ out via ROMK. Takes 30-90 min (genomic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','Describe the mechanism by which ADH (vasopressin) increases water permeability of the collecting duct.','["ADH pathway: ADH binds V2 receptor (Gs-coupled GPCR) on basolateral membrane of principal cells → Gs activates adenylyl cyclase → cAMP rises → PKA is activated → PKA phosphorylates AQP2 on serine-256 → AQP2-containing vesicles (from subapical storage pool) fuse with apical membrane → water channels inserted. Water can now cross apically via AQP2, and exit basolaterally via constitutive AQP3 and AQP4. Long-term: ADH also upregulates AQP2 gene transcription via CREB. Removal of ADH → endocytosis of AQP2 back into vesicles within minutes. Lithium blocks the PKA step; demeclocycline also blocks cAMP signalling."]','A','ADH → V2R (Gs) → cAMP → PKA → phosphorylates AQP2-Ser256 → vesicle fusion → apical AQP2 insertion → water permeability↑. Lithium blocks PKA step. AQP3/4 constitutive basolaterally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','What is the difference between Gitelman syndrome and Bartter syndrome in terms of genetic defect, electrolytes, and calcium handling?','["GITELMAN SYNDROME: NCC mutation (SLC12A3, DCT Na-Cl cotransporter) — like chronic thiazide use. Features: hypokalaemia, metabolic alkalosis, hypomagnesaemia, HYPOCALCIURIA (DCT also reabsorbs Ca2+ via TRPV5; thiazide/NCC blockade increases Ca2+ reabsorption here). Usually mild, adult presentation. BARTTER SYNDROME: NKCC2 (type I), ROMK (type II), ClC-Kb (type III), or Barttin (type IV) mutations — TAL dysfunction. Features: hypokalaemia, metabolic alkalosis, HYPERCALCIURIA (TAL provides driving force for paracellular Ca2+ reabsorption; loss → Ca2+ wasting). Often severe, neonatal presentation. Mnemonic: Gitelman = Gentle (mild, hypocalciuria); Bartter = Bad (severe, hypercalciuria)."]','A','Gitelman (NCC/DCT) = thiazide phenotype: HYPOcalciuria, hypomagnesaemia, mild, adult. Bartter (NKCC2/TAL) = furosemide phenotype: HYPERcalciuria, severe, neonatal. Calcium handling is the key distinguisher.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','How does amiloride differ from spironolactone in its mechanism and in which conditions each is preferred?','["AMILORIDE: Directly blocks ENaC channels in the collecting duct apical membrane → reduces Na+ reabsorption and K+ secretion, independently of aldosterone levels. Used in: Liddle syndrome (constitutively active ENaC regardless of aldosterone), lithium-induced nephrogenic DI (blocks Li+ entry via ENaC), and as K+-sparing adjunct. SPIRONOLACTONE (and eplerenone): Competitive antagonist of aldosterone at mineralocorticoid receptor → reduces ENaC and Na-K-ATPase expression. Requires endogenous aldosterone to have an effect. Used in: primary hyperaldosteronism, heart failure (RAAS-driven), cirrhosis with ascites. Spironolactone FAILS in Liddle syndrome (no aldosterone involvement)."]','A','Amiloride: blocks ENaC directly (aldosterone-independent). Use in Liddle syndrome, Li-induced DI. Spironolactone: MR antagonist (needs aldosterone present). Use in hyperaldosteronism, HF, cirrhosis. Spironolactone fails in Liddle (no MR excess).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','Describe the alpha-intercalated cell: what does it secrete, what transporters are involved, and when is it most active?','["Alpha-intercalated cell (type A) — the main urinary acidification cell: APICAL: H+-ATPase (V-type proton pump) secretes H+ into lumen; H+-K+-ATPase (also apical) secretes H+ while reabsorbing K+. INTRACELLULAR: Carbonic anhydrase II: CO2 + H2O → H+ + HCO3-; H+ secreted apically; HCO3- exits BASOLATERALLY via AE1 (anion exchanger 1, Cl-/HCO3- exchanger) into blood. WHEN MOST ACTIVE: Metabolic acidosis, volume depletion (aldosterone stimulates H+ secretion via H+-ATPase upregulation), hypokalaemia (K+ is reabsorbed apically while H+ is secreted). Net effect: H+ excreted, HCO3- added to blood. Failure of this cell → type 1 distal RTA."]','A','Alpha-IC: apical H+-ATPase + H+-K+-ATPase secrete H+; basolateral AE1 exports HCO3-. Active in acidosis/hypokalaemia/aldosterone excess. Loss-of-function → type 1 distal RTA (inability to acidify urine below pH 5.5).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','What is nephrogenic diabetes insipidus, and name three causes?','["Nephrogenic DI: The collecting duct is unable to respond to ADH (levels are HIGH but effect is absent), resulting in large volumes of dilute urine (polyuria >3 L/day, osmolality <300 mOsm/kg) despite dehydration. Three causes: (1) X-linked: V2 receptor mutations (most common hereditary form, males affected); (2) Autosomal recessive: AQP2 mutations; (3) Acquired: lithium toxicity (most common acquired cause — blocks cAMP signalling via ENaC entry), hypercalcaemia (>11 mg/dL — reduces AQP2 expression and causes vasoconstriction of vasa recta), chronic hypokalaemia (downregulates AQP2). Treatment: thiazides + low-Na/low-protein diet (reduces filtered solute load → less obligatory water excretion)."]','A','Nephrogenic DI: high ADH but collecting duct unresponsive → polyuria, dilute urine. Causes: V2R mutation (X-linked), AQP2 mutation (AR), lithium (acquired, most common), hypercalcaemia, hypokalaemia. Treat with thiazide + low-solute diet.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','medium','flashcard','How does the DCT (distal convoluted tubule) handle calcium, and which transporter is the apical entry channel?','["DCT is the main site of active transcellular Ca2+ reabsorption (~10-15% of filtered Ca2+). Apical entry: TRPV5 (transient receptor potential vanilloid 5) — the primary Ca2+ entry channel in DCT. Intracellular: Ca2+ bound to calbindin-D28K (prevents free Ca2+ toxicity); transcellular transport. Basolateral exit: NCX1 (Na-Ca exchanger, 3 Na+ in / 1 Ca2+ out) and PMCA (Ca2+-ATPase). Regulation: PTH and 1,25(OH)2D3 upregulate TRPV5; thiazides (blocking NCC) cause cell hyperpolarisation → increased TRPV5 driving force → more Ca2+ reabsorption → hypocalciuria (used for calcium nephrolithiasis). Furosemide blocks paracellular TAL Ca2+ absorption → hypercalciuria."]','A','DCT Ca2+: apical TRPV5 (regulated by PTH, 1,25-D3) → calbindin → NCX1/PMCA basolateral. Thiazides block NCC → hyperpolarisation → TRPV5↑ → hypocalciuria. Used for Ca2+ kidney stones.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','hard','flashcard','Explain why chronic metabolic alkalosis leads to potassium wasting in the collecting duct.','["Chronic alkalosis → K+ wasting via multiple mechanisms: (1) Alkalosis directly stimulates ROMK channel activity (open probability increases at alkaline pH) → more K+ secretion. (2) Volume contraction often accompanies alkalosis (e.g., vomiting) → RAAS activation → aldosterone upregulates ENaC (more lumen negativity → more ROMK-driven K+ secretion) and ROMK directly. (3) High HCO3- delivery to collecting duct creates a non-reabsorbable anion effect: HCO3- in the lumen increases lumen negativity, further driving K+ secretion. (4) Alkalosis shifts K+ into cells transiently, raising aldosterone via feedback. Net: profound hypokalaemia can develop in chronic metabolic alkalosis."]','A','Alkalosis → K+ wasting: (1) alkaline pH opens ROMK; (2) volume contraction → aldosterone → ENaC/ROMK up; (3) luminal HCO3- non-reabsorbable anion → lumen more negative → K+ secreted. Classic vomiting → profound hypokalaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Distal Tubule & Collecting Duct','hard','flashcard','What is the physiology behind the ''''aldosterone escape'''' phenomenon and in which conditions does it occur?','["Aldosterone escape: When aldosterone is chronically elevated (primary hyperaldosteronism or exogenous mineralocorticoids), initially Na+ is retained and volume expands. However, with continued volume expansion: (1) Atrial stretch releases ANP → inhibits ENaC, NCC, and NHE3; (2) Elevated blood pressure causes pressure-natriuresis (increased medullary interstitial pressure, reduced peritubular reabsorption); (3) GFR may increase slightly; (4) Supressed RAAS activity in the macula densa. Together, these mechanisms cause Na+ excretion to increase back toward intake, re-establishing Na+ balance despite ongoing high aldosterone. Volume expansion stabilises but remains elevated (causing hypertension). Hypokalaemia and metabolic alkalosis persist because aldosterone continues to drive K+ and H+ secretion via mechanisms that don''''t ''''escape.''''"]','A','Aldosterone escape: chronic hyperaldosteronism → initial Na+ retention → volume expansion → ANP + pressure-natriuresis → Na+ balance restored despite high aldosterone. Hypertension persists. Hypokalaemia/alkalosis DO NOT escape — clinically distinguishes 1° from 2° hyperaldosteronism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','easy','flashcard','What percentage of filtered bicarbonate is reabsorbed in the proximal tubule, and what enzyme is essential for this process?','["~80% of filtered HCO3- is reabsorbed in the PCT (and a further ~15% in the thick ascending limb, with the remaining ~5% in the collecting duct). The essential enzymes are carbonic anhydrase IV (brush border — converts H2CO3 to CO2+H2O in the lumen) and carbonic anhydrase II (intracellular — rehydrates CO2 back to H2CO3). Acetazolamide inhibits both, blocking this process and causing bicarbonaturia and a self-limited metabolic acidosis. Without CA, H2CO3 would accumulate in the lumen, back-diffusing H+ and preventing further bicarbonate reabsorption."]','A','Carbonic anhydrase IV and II mediate ~80% PCT HCO3- reabsorption; acetazolamide inhibits both causing bicarbonaturia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','easy','flashcard','What are the three forms of renal net acid excretion, and which is quantitatively most important in chronic acidosis?','["The kidney excretes net acid in three forms: (1) Titratable acids: mainly H2PO4- (phosphate buffer, pKa 6.8) — excretes ~30-40 mEq/day normally; (2) Ammonium (NH4+): PCT produces NH3/NH4+ from glutamine; excretes ~40-60 mEq/day normally but can increase to >200-300 mEq/day in chronic acidosis; (3) Free H+ in urine (trivial — even at pH 4.5, only ~0.03 mEq/L). In chronic metabolic acidosis, AMMONIUM excretion is quantitatively most important — it can increase 5-10 fold via upregulation of renal ammoniagenesis (glutaminase upregulation). This represents the kidney''s main adaptive response to sustained acid loads."]','A','Ammonium excretion is most important in chronic acidosis, rising from ~50 to >200 mEq/day via glutaminase upregulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','Describe the ammonium recycling pathway in the kidney and how it amplifies urinary acid excretion.','["Ammonium recycling: (1) PCT cells metabolise glutamine via phosphate-dependent glutaminase → 2 NH4+ + alpha-ketoglutarate (further metabolised → 2 HCO3- returned to blood). (2) NH4+ is secreted into PCT lumen via NHE3 (substituting for H+). (3) In the TAL, NH4+ (same size as K+) substitutes for K+ on NKCC2 → reabsorbed into medullary interstitium. (4) NH3 (lipid-soluble) diffuses from interstitium into collecting duct lumen. (5) Collecting duct H+ (from alpha-intercalated cells) combines with NH3 → NH4+ trapped (membrane impermeant) → excreted. Recycling through the medullary interstitium concentrates NH3/NH4+ (similar to urea recycling), maximising NH4+ secretion in the collecting duct. Each mole of NH4+ excreted = 1 mole of H+ excreted + 1 mole of HCO3- regenerated."]','A','NH4+ cycles through TAL interstitium then diffuses as NH3 into collecting duct where it traps H+; each mole excreted regenerates 1 mole HCO3-.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','Distinguish type 1 (distal), type 2 (proximal), and type 4 renal tubular acidosis by defect, urine pH, potassium, and key complication.','["TYPE 1 (distal RTA): Defect — alpha-intercalated cell H+-ATPase (or AE1); urine pH >5.5 despite acidosis; hypokalaemia (RAAS activation); complication — nephrocalcinosis + kidney stones (alkaline urine + hypercalciuria/hypocitraturia → calcium phosphate stones). TYPE 2 (proximal RTA): Defect — PCT HCO3- reabsorption threshold lowered; urine pH >5.5 initially (spilling HCO3-) but <5.5 once plasma HCO3- falls below new threshold; hypokalaemia; complication — osteomalacia (phosphaturia, low 1,25(OH)2D); no nephrocalcinosis. TYPE 4 (hyperkalaemic RTA): Defect — aldosterone deficiency/resistance; urine pH NORMAL (<5.5 — acidification intact but NH4+ production impaired by hyperkalaemia); HYPERKALAEMIA; complication — cardiac arrhythmia from hyperkalaemia. Common cause: diabetic hyporeninism."]','A','Type 1: distal H+-ATPase defect, urine pH>5.5, hypokalaemia, nephrocalcinosis. Type 2: PCT threshold defect, osteomalacia. Type 4: aldosterone deficiency/resistance, hyperkalaemia, normal urine pH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','How does chronic metabolic acidosis stimulate the kidneys to increase ammoniagenesis over days?','["Adaptation to chronic metabolic acidosis (hours to days): (1) Acidosis upregulates expression of phosphate-dependent glutaminase (PDG) and glutamate dehydrogenase in PCT cells via pH-sensitive mRNA stability elements (AU-rich elements). (2) Upregulation of SNAT3 (basolateral glutamine transporter) increases glutamine uptake. (3) Increased alpha-ketoglutarate metabolism generates more HCO3- for blood buffering. (4) Upregulation of NHE3 and NKCC2 (TAL) improves NH4+ delivery to medullary interstitium. (5) Upregulation of rhesus glycoproteins (Rhcg/Rhbg) in the collecting duct facilitates NH3 diffusion. Net result: NH4+ excretion rises from 40 to >200 mEq/day over 3-5 days. This is the major adaptive response to sustained metabolic acidosis."]','A','Acidosis upregulates PDG/glutamate dehydrogenase via mRNA stability elements; NH4+ excretion rises from ~40 to >200 mEq/day over 3-5 days.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','What is the urinary anion gap (UAG) formula and how does it help diagnose the cause of normal anion gap metabolic acidosis?','["UAG = [Na+]urine + [K+]urine − [Cl-]urine. Logic: urine electroneutrality requires that all cations = anions. NH4+ is an unmeasured cation. If NH4+ excretion is HIGH (appropriate renal response to acidosis), Cl- will be high to balance Na++K++NH4+, making Cl- > Na++K+ → UAG NEGATIVE (e.g., −20 to −50 mEq/L). If NH4+ excretion is LOW (RTA — kidney not responding properly), Na++K+ ≈ Cl- → UAG near ZERO or POSITIVE. Interpretation: Negative UAG = appropriate renal acid excretion (GI cause of acidosis, e.g., diarrhoea). Positive/zero UAG = impaired renal NH4+ excretion → renal tubular acidosis or renal failure."]','A','UAG = Na+urine + K+urine - Cl-urine. Negative UAG = high NH4+ (GI cause); positive/zero UAG = impaired NH4+ excretion (RTA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','Why does respiratory alkalosis (hyperventilation) cause plasma bicarbonate to fall, and by how much?','["In respiratory alkalosis, low pCO2 reduces the substrate for HCO3- generation (H2CO3 → H+ + HCO3-). Immediate (minutes): less CO2 available → less H2CO3 → less HCO3- generated; blood pH rises. Renal compensation (days): low pCO2 reduces H+ secretion in PCT (less CO2 to form H2CO3 intracellularly → less NHE3 drive) → HCO3- is not fully reabsorbed → HCO3- wasted in urine → plasma HCO3- falls. Expected compensation: for every 1 mmHg fall in pCO2, plasma HCO3- falls by ~0.2 mEq/L acutely (buffering) and ~0.4-0.5 mEq/L chronically (renal). This renal adaptation takes 2-5 days to complete and represents appropriate physiological compensation, not a second acid-base disorder."]','A','Each 1 mmHg fall in pCO2 lowers HCO3- by ~0.2 mEq/L acutely and ~0.4-0.5 mEq/L chronically via reduced NHE3 drive.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','medium','flashcard','How does aldosterone regulate urinary acid excretion via alpha-intercalated cells?','["Aldosterone stimulates H+ secretion in alpha-intercalated cells by: (1) Increasing Na+ reabsorption via ENaC in principal cells → more lumen-negative transepithelial potential → creates a more favourable electrical gradient for H+ secretion by adjacent alpha-intercalated cells; (2) Directly upregulating H+-ATPase expression in alpha-intercalated cells (mineralocorticoid receptors present). Net effect: volume depletion or primary hyperaldosteronism → increased H+ secretion → metabolic alkalosis (in addition to hypokalaemia). This is why metabolic alkalosis and hypokalaemia co-occur in hyperaldosteronism. Conversely, aldosterone deficiency (Addison''s, type 4 RTA) impairs H+ secretion → metabolic acidosis."]','A','Aldosterone stimulates H+ secretion indirectly (ENaC-driven lumen negativity) and directly (H+-ATPase upregulation); deficiency causes type 4 RTA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','hard','flashcard','Explain the pathophysiology of metabolic alkalosis maintenance — why does the kidney fail to correct it despite theoretically being able to excrete excess HCO3-?','["Metabolic alkalosis is GENERATED (e.g., vomiting → HCl loss) but MAINTAINED by factors that prevent the kidney from excreting excess HCO3-: (1) Volume depletion (from Cl- loss) → RAAS activation → aldosterone → ENaC-driven Na+ reabsorption → HCO3- reabsorbed to maintain electroneutrality (insufficient luminal Cl- as the co-ion); (2) Hypokalaemia → K+ shifts out of cells, H+ shifts into cells → intracellular acidosis in tubular cells → stimulates NHE3 and H+-ATPase → continued H+ secretion and HCO3- reabsorption; (3) Low luminal Cl- reduces AE1 activity in alpha-IC cells (needs Cl- for HCO3- exchange). Treatment: volume and Cl- replacement → restores conditions for HCO3- excretion (Cl--sensitive alkalosis)."]','A','Metabolic alkalosis is maintained by volume depletion (RAAS activation), hypokalaemia (intracellular acidosis), and low luminal Cl-; treated with volume and Cl- replacement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Acid-Base Regulation','hard','flashcard','In uremic acidosis (advanced CKD), why is the anion gap elevated, and which anions accumulate?','["In advanced CKD (GFR <20-30 mL/min), unmeasured anions accumulate because: (1) Insufficient nephron mass to filter and excrete them; (2) Organic acids from incomplete metabolism accumulate (hippurate, indoxyl sulphate, p-cresyl sulphate); (3) Retained sulphate (from protein metabolism) and phosphate (from phospholipid/nucleic acid catabolism); (4) Reduced NH4+ excretion (not enough PCT cells to generate sufficient ammonium). These anions replace the missing HCO3- (which falls as net acid accumulates), raising the anion gap. Anion gap = [Na+] − [Cl-] − [HCO3-] rises above 12 mEq/L. The same pattern (high AG metabolic acidosis) occurs in lactic acidosis, ketoacidosis, and salicylate poisoning but for different reasons. In early CKD (GFR 30-60), normal AG acidosis predominates (reduced NH4+ but no organic acid accumulation yet)."]','A','In advanced CKD, sulphate, phosphate, hippurate, and indoxyl sulphate accumulate, elevating the anion gap; early CKD causes normal AG acidosis from reduced NH4+ excretion alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','easy','flashcard','What fraction of filtered potassium is reabsorbed in the proximal tubule and thick ascending limb, and what percentage reaches the distal nephron?','["Of the filtered K+ load: ~65% is reabsorbed in the PCT (passively, via solvent drag and paracellular route following Na+/water reabsorption). ~25-30% is reabsorbed in the TAL (K+ recycles via apical ROMK after NKCC2 import; some paracellular reabsorption). Approximately 5-10% reaches the distal nephron (DCT and collecting duct) for regulated secretion or further reabsorption. The distal nephron is the primary site of K+ regulation — in states of K+ excess, principal cells secrete additional K+ via ROMK and BKCa channels; in K+ depletion, alpha-IC cells reabsorb K+ via apical H+-K+-ATPase."]','A','PCT reabsorbs ~65%, TAL ~25-30%; only 5-10% reaches the distal nephron where regulated secretion or reabsorption occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','easy','flashcard','What is ROMK (Kir1.1) and what is its physiological role in K+ excretion?','["ROMK (renal outer medullary K+ channel, Kir1.1, encoded by KCNJ1) is a constitutively open inwardly-rectifying K+ channel on the apical membrane of principal cells. It mediates K+ secretion into the tubular lumen. Driving force: high intracellular K+ (from basolateral Na-K-ATPase) and lumen-negative electrical potential (from ENaC Na+ entry). Aldosterone upregulates ROMK expression. ROMK also plays a critical role in recycling K+ to the TAL lumen (providing K+ for NKCC2 to function, since blood [K+] is low relative to Na+ and Cl-). Loss-of-function ROMK mutations → Bartter syndrome type II (transient hyperkalaemia in neonates, then hypokalaemia)."]','A','ROMK (Kir1.1) on principal cell apical membrane mediates K+ secretion driven by intracellular K+ gradient and lumen negativity; loss-of-function causes Bartter syndrome type II.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','List four factors that INCREASE potassium secretion in the collecting duct and explain the mechanism for each.','["Factors increasing K+ secretion: (1) HIGH ALDOSTERONE: upregulates ENaC (more lumen negativity) and ROMK (more channels) → increased driving force and channel density for K+ secretion. (2) HIGH PLASMA [K+]: directly stimulates Na-K-ATPase (more intracellular K+) and ROMK open probability; also stimulates aldosterone secretion. (3) HIGH TUBULAR FLOW RATE: dilutes luminal K+ (washes away secreted K+, maintaining concentration gradient for secretion); also activates mechanosensitive BKCa channels. (4) METABOLIC ALKALOSIS: directly increases ROMK open probability (ROMK is pH-sensitive); alkalosis also shifts K+ into cells, reflexly increasing aldosterone. Inverse of each factor decreases K+ secretion."]','A','High aldosterone, high plasma K+, high tubular flow, and metabolic alkalosis all increase collecting duct K+ secretion via distinct mechanisms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','Explain the transcellular K+ shifts with acidosis and alkalosis.','["Transcellular shifts regulate plasma [K+] rapidly (within minutes): ACIDOSIS (especially mineral acids: HCl, H2SO4): H+ enters cells for buffering → to maintain electroneutrality, K+ exits cells → HYPERKALAEMIA (~0.6 mEq/L rise per 0.1 pH unit drop). Note: organic acids (lactic acid, ketoacids) cause minimal K+ shift because organic anions enter cells with H+, preserving electroneutrality. ALKALOSIS: H+ leaves cells (to partially buffer alkalosis) → K+ enters cells → HYPOKALAEMIA (~0.3 mEq/L fall per 0.1 pH unit rise). Also: insulin and beta-2 agonists drive K+ into cells; alpha-agonists cause K+ release. Exercise: K+ released from contracting muscle → transient hyperkalaemia → stimulates aldosterone for renal correction."]','A','Mineral acid acidosis causes hyperkalaemia (~0.6 mEq/L per 0.1 pH unit); alkalosis causes hypokalaemia (~0.3 mEq/L per 0.1 pH unit). Organic acids cause minimal K+ shift.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','How do loop diuretics cause hypokalaemia via both direct and indirect mechanisms?','["Loop diuretics cause hypokalaemia through: (1) DIRECT: blocking NKCC2 in the TAL prevents K+ reabsorption at this site. Increased K+ delivery to the DCT/collecting duct. (2) TUBULAR FLOW: increased flow rate to the collecting duct washes away secreted K+, maintaining the concentration gradient for ROMK-mediated K+ secretion and activating BKCa channels. (3) VOLUME DEPLETION: natriuresis and volume contraction → RAAS activation → aldosterone rises → ENaC upregulated (more lumen negativity) → more K+ secretion via ROMK. (4) METABOLIC ALKALOSIS (loop diuretics cause): alkalosis directly increases ROMK open probability. Together, these mechanisms cause significant hypokalaemia requiring K+ supplementation with long-term loop diuretic use."]','A','Loop diuretics cause hypokalaemia via NKCC2 blockade, increased distal flow, RAAS-driven aldosterone, and concomitant metabolic alkalosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','What are the renal mechanisms for potassium conservation during K+ depletion?','["K+ conservation during depletion: (1) ROMK closure: intracellular alkalosis (from K+ depletion) and reduced intracellular K+ reduce ROMK channel activity → less K+ secretion. (2) H+-K+-ATPase upregulation in alpha-intercalated cells: secretes H+ while reabsorbing K+ from the tubular lumen → K+ reabsorption (at the cost of H+ secretion → metabolic alkalosis in severe hypokalaemia). (3) Reduced aldosterone (if K+ depletion reduces adrenal stimulation): less ENaC drive → less ROMK-driven K+ secretion. (4) Reduced tubular flow rate (if volume-deplete) → less flow-stimulated K+ secretion. Minimum urinary K+ in severe depletion: ~10-15 mEq/L (still some obligatory K+ loss). Compared to Na+, the kidney conserves K+ less effectively — significant losses occur before excretion falls to minimum."]','A','K+ depletion closes ROMK, upregulates H+-K+-ATPase (causes alkalosis), reduces aldosterone, and lowers flow; minimum urinary K+ ~10-15 mEq/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','What is pseudohypoaldosteronism type 1 (PHA1) and how does it differ from Addison''s disease?','["PHA1: Aldosterone RESISTANCE (high aldosterone, high renin, but kidney cannot respond). Two forms: (1) Autosomal dominant: mineralocorticoid receptor mutations → partial resistance; milder. (2) Autosomal recessive: ENaC subunit mutations (SCNN1A/B/G) → complete ENaC dysfunction → severe salt wasting, hyperkalaemia, metabolic acidosis, AND lung disease (ENaC expressed in airway epithelium). ADDISON''S DISEASE: Aldosterone DEFICIENCY (low aldosterone, high renin) → same electrolytes (hyperkalaemia, hyponatraemia, metabolic acidosis) but aldosterone is low. Key distinction: in PHA1, exogenous aldosterone (fludrocortisone) has NO effect (resistance); in Addison''s, fludrocortisone corrects the abnormality. Treatment of recessive PHA1: high-salt diet + ion exchange resins; some improve with age as skin and lung abnormalities lessen."]','A','PHA1 = aldosterone resistance (high aldo, no response); Addison''s = aldosterone deficiency (low aldo). Fludrocortisone corrects Addison''s but not PHA1.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','medium','flashcard','What are BKCa (maxi-K) channels in the collecting duct, and under what conditions do they contribute significantly to K+ secretion?','["BKCa (large conductance calcium-activated K+, KCNMA1/BK) channels in the collecting duct are activated by: (1) High tubular flow rate (mechanosensitive — increased stretch/flow activates them); (2) High intracellular Ca2+ (transient rises during high-flow/high-aldosterone states); (3) Aldosterone (increases BKCa expression). Under BASAL conditions, ROMK is the dominant K+ secretory channel. BKCa becomes important during: high urine flow (loop diuretics, high water intake), high dietary K+ intake (especially when combined with high flow), exercise-induced K+ load. BKCa channels are on BOTH principal cells AND intercalated cells in the CCD. Their high conductance allows rapid K+ secretion during flow-stimulated kaliuresis."]','A','BKCa channels are flow- and Ca2+-activated; they supplement ROMK during high urine flow states and high K+ loading.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','hard','flashcard','A patient on chronic trimethoprim develops hyperkalaemia. Explain the mechanism and how it differs from spironolactone-induced hyperkalaemia.','["TRIMETHOPRIM mechanism: Structurally similar to amiloride → directly blocks ENaC in the collecting duct principal cells → reduced Na+ reabsorption → less lumen-negative potential → less driving force for ROMK-mediated K+ secretion → hyperkalaemia + mild acidosis. Dose-dependent; significant at doses used for PCP prophylaxis (960 mg/day TMP-SMX). SPIRONOLACTONE mechanism: Blocks mineralocorticoid receptor → reduces aldosterone-stimulated ENaC and ROMK expression → hyperkalaemia. Spironolactone requires intact aldosterone for its effect. KEY DIFFERENCE: Trimethoprim acts DIRECTLY on ENaC (like amiloride) regardless of aldosterone levels; spironolactone only reduces K+ secretion if there is endogenous aldosterone activity to block. Both cause hyperkalaemia + mild metabolic acidosis (type 4-like RTA pattern)."]','A','Trimethoprim blocks ENaC directly (amiloride-like); spironolactone blocks the mineralocorticoid receptor. Both cause hyperkalaemia and type 4-like RTA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Potassium Handling','hard','flashcard','Why does hypokalaemia cause metabolic alkalosis, and why does metabolic alkalosis cause hypokalaemia? (Explain the bidirectional relationship.)','["HYPOKALAEMIA → METABOLIC ALKALOSIS: (1) K+ depletion causes K+ to shift out of cells and H+ to shift in (to maintain electroneutrality) → intracellular acidosis in PCT and intercalated cells → stimulates NHE3 (increased H+ secretion/HCO3- reabsorption) and H+-ATPase → net HCO3- accumulates in blood. (2) K+ depletion directly upregulates H+-K+-ATPase in alpha-IC cells → more H+ secretion into urine. (3) K+ depletion stimulates aldosterone (? uncertain) → more H+ secretion. METABOLIC ALKALOSIS → HYPOKALAEMIA: (1) Alkaline tubular fluid increases ROMK open probability → more K+ secretion. (2) High luminal HCO3- (non-reabsorbable anion) increases lumen negativity → more K+ secretion. (3) Vomiting-induced alkalosis involves volume depletion → aldosterone → K+ secretion. These reinforce each other, making combined hypokalaemia/alkalosis self-perpetuating until volume and Cl- are replaced."]','A','Hypokalaemia causes intracellular acidosis → more NHE3/H+-ATPase activity → alkalosis. Alkalosis increases ROMK activity and lumen negativity → more K+ secretion → hypokalaemia. Self-perpetuating cycle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','easy','flashcard','What are the three triggers for renin secretion from juxtaglomerular cells?','["Three triggers for renin release from JG (granular) cells in the afferent arteriole: (1) REDUCED AFFERENT ARTERIOLE WALL STRETCH (baroreceptor mechanism): low renal perfusion pressure is sensed directly by afferent arteriole smooth muscle → renin released. (2) DECREASED NaCl DELIVERY TO MACULA DENSA: sensed by NKCC2 on macula densa cells; low NaCl → paracrine signals (PGE2, NO) → renin release. (3) INCREASED SYMPATHETIC ACTIVITY: beta-1 adrenoceptors on JG cells stimulated by norepinephrine → cAMP → renin exocytosis. All three trigger the full RAAS cascade: renin → angiotensinogen → Ang I → (ACE) → Ang II → aldosterone, efferent constriction, thirst, ADH."]','A','Renin is released by reduced afferent stretch (baroreceptor), reduced NaCl at macula densa, and beta-1 sympathetic stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','easy','flashcard','What are the major cardiovascular and renal effects of angiotensin II?','["Angiotensin II (AT1 receptor-mediated) effects: VASCULAR: potent vasoconstriction (all vessels) → raises blood pressure; preferential efferent arteriole constriction → maintains GFR despite low renal perfusion. RENAL TUBULAR: stimulates NHE3 in PCT → increased Na+ and HCO3- reabsorption (anti-natriuresis); stimulates Na-K-ATPase in PCT. ADRENAL: stimulates aldosterone secretion from zona glomerulosa → Na+ retention and K+ excretion via ENaC/ROMK in collecting duct. HYPOTHALAMUS: stimulates thirst and ADH release (V2 pathway → AQP2 insertion). SYMPATHETIC: potentiates sympathetic neurotransmission. NET: sodium and water retention, vasoconstriction, raised blood pressure — a comprehensive anti-hypotensive response."]','A','Ang II causes vasoconstriction (preferentially efferent), NHE3-driven Na+ reabsorption, aldosterone release, thirst/ADH stimulation — a comprehensive anti-hypotensive response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','Explain the pressure-natriuresis relationship and its role in long-term blood pressure regulation.','["Pressure-natriuresis: when renal perfusion pressure rises, the kidney excretes more Na+ and water; when pressure falls, Na+ is retained. Mechanisms: (1) Higher perfusion pressure → increased medullary interstitial hydrostatic pressure → reduced peritubular capillary oncotic-driven reabsorption from PCT and loop → more Na+ and water excreted; (2) Increased renal interstitial pressure → prostaglandin and nitric oxide release → inhibit tubular Na+ transport; (3) Higher pressure → reduced renin (stretch suppresses JG cells) → less Ang II → less NHE3 and ENaC activity. Long-term significance: blood pressure is ultimately set by the kidney''s ability to excrete Na+ to match intake. ANY sustained hypertension requires the pressure-natriuresis curve to be reset to a higher operating point (via RAAS, sympathetics, or structural kidney changes)."]','A','Pressure-natriuresis links renal perfusion pressure to Na+ excretion; long-term BP is set by the kidney, requiring curve reset for sustained hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','How do prostaglandins protect the kidney during states of low renal perfusion, and which drugs block this protection?','["Renal prostaglandins (PGE2, PGI2) are produced by medullary interstitial cells, mesangial cells, and endothelium in response to vasoconstrictor stimuli (Ang II, sympathetics, endothelin). They act as LOCAL VASODILATORS at the afferent arteriole, counterbalancing vasoconstriction and maintaining RBF and GFR. Under normal conditions, their role is modest. Under LOW PERFUSION (heart failure, cirrhosis, volume depletion, RAS), prostaglandins are critical for maintaining GFR. NSAIDs (COX-1 and COX-2 inhibitors) block prostaglandin synthesis → unopposed vasoconstriction → acute kidney injury in at-risk patients. Selective COX-2 inhibitors also impair renal prostaglandins. This is why NSAIDs are contraindicated in heart failure, cirrhosis, CKD, and volume depletion."]','A','PGE2/PGI2 dilate the afferent arteriole to protect GFR during low perfusion states; NSAIDs block this, causing AKI in susceptible patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','What are the effects of atrial natriuretic peptide (ANP) on the kidney and RAAS?','["ANP (released from atrial myocytes when stretched by volume overload) → cGMP in target cells. Renal effects: (1) Dilates afferent arteriole + constricts efferent arteriole → increases GFR (natriuresis via filtered load); (2) Directly inhibits ENaC in the collecting duct → reduces Na+ reabsorption; (3) Inhibits NCC in DCT; (4) Dilates vasa recta → ''washes out'' medullary gradient slightly → reduces concentrating ability. RAAS effects: (5) Inhibits renin secretion from JG cells; (6) Inhibits aldosterone secretion from adrenal zona glomerulosa; (7) Inhibits ADH secretion and collecting duct response to ADH. NET: strongly natriuretic, diuretic, and vasodilatory — the physiological counterpart to RAAS. BNP (from ventricles) has similar but weaker renal effects."]','A','ANP increases GFR, inhibits ENaC/NCC, suppresses renin/aldosterone/ADH — it is the physiological counter-regulatory system to RAAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','Why can ACE inhibitors cause acute kidney injury in patients with heart failure, bilateral renal artery stenosis, or volume depletion?','["In these conditions, GFR depends on angiotensin II-mediated preferential efferent arteriole constriction to maintain glomerular hydrostatic pressure. When renal perfusion pressure is low (heart failure, bilateral RAS, volume depletion), the kidney upregulates renin → Ang II → efferent constriction preserves GFR. ACE inhibitors (or ARBs) block Ang II production → efferent arteriole dilates → glomerular hydrostatic pressure falls → GFR drops. The susceptibility is greatest when BOTH the afferent arteriole is already maximally dilated (by autoregulation responding to low pressure) AND the efferent tone is all that remains to maintain filtration pressure. In bilateral RAS, BOTH kidneys are simultaneously at risk, making AKI rapid and severe."]','A','When GFR depends on Ang II-driven efferent constriction (low perfusion states), ACE inhibitors drop glomerular pressure → AKI; bilateral RAS carries highest risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','How does the dopamine system in the kidney regulate sodium excretion?','["Intrarenal dopamine is produced by PCT cells from circulating and locally-generated L-dopa (by aromatic amino acid decarboxylase). Dopamine actions (via D1-like receptors): (1) Inhibits NHE3 in PCT → reduced Na+ and HCO3- reabsorption; (2) Inhibits Na-K-ATPase in PCT basolateral membrane; (3) Inhibits aldosterone secretion from adrenal; (4) Vasodilates afferent arteriole (D1 receptor) → increased RBF and GFR → natriuresis. In volume expansion, dopamine production increases → natriuresis (a physiological counter-regulatory system). Dopamine receptor agonists (low-dose dopamine infusion — ''renal dose dopamine'') were used to increase RBF in AKI, but clinical trials showed no benefit and this practice has been largely abandoned."]','A','Intrarenal dopamine (D1 receptors) inhibits NHE3 and Na-K-ATPase, reduces aldosterone, and dilates afferent arteriole; ''renal dose dopamine'' for AKI showed no clinical benefit.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','medium','flashcard','What is the tubuloglomerular feedback reset, and why does it occur in high-protein diets or after uninephrectomy?','["TGF reset (also called ''glomerulotubular balance disruption''): under normal conditions, TGF tightly couples GFR to tubular reabsorptive capacity. After UNINEPHRECTOMY or in HIGH-PROTEIN DIETS, the remaining nephrons undergo hyperfiltration — their individual GFR increases. For this to occur chronically, the TGF set point must reset: macula densa cells recalibrate their NaCl-sensing threshold upward, accepting more NaCl delivery without triggering afferent vasoconstriction. This allows sustained hyperfiltration. Mechanisms of reset: nitric oxide from macula densa, angiotensin II, prostaglandins, and changes in NKCC2 expression all contribute. Long-term hyperfiltration → glomerular hypertension → progressive sclerosis (mechanism of CKD progression in donors and patients with reduced nephron mass)."]','A','TGF reset allows hyperfiltration after nephron loss by raising the macula densa NaCl threshold; chronic hyperfiltration causes progressive glomerulosclerosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','hard','flashcard','Explain the differential effects of angiotensin II on the afferent vs efferent arterioles, and how this changes with high vs low Ang II concentrations.','["Angiotensin II preferentially constricts the EFFERENT arteriole at physiological concentrations because: (1) The efferent arteriole has higher AT1 receptor density; (2) Intrarenal Ang II levels are highest near the efferent arteriole (local generation). Effect at LOW Ang II: mild efferent constriction → GFR maintained or slightly increased; RBF mildly reduced. Effect at HIGH Ang II (severe underperfusion, exogenous infusion): BOTH afferent and efferent arterioles constrict → RBF falls dramatically → despite efferent constriction trying to maintain GFR, afferent constriction ultimately wins → GFR falls. At extremely high Ang II: mesangial cell contraction reduces Kf → GFR falls further. This explains why ACE inhibitors (reducing Ang II) increase GFR in mild renovascular disease but the relationship is complex in severe disease."]','A','At low levels, Ang II preferentially constricts efferent (higher AT1 density) preserving GFR; at high levels, both arterioles constrict, falling RBF and GFR dominate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','RAAS & Renal Blood Flow','hard','flashcard','What is the role of endothelin-1 (ET-1) in the kidney during AKI, and how do ETA and ETB receptors have opposing roles?','["ET-1 in AKI: Released by ischaemic/stressed renal endothelial and tubular cells. ETA RECEPTORS (on vascular smooth muscle): mediate profound vasoconstriction of afferent and efferent arterioles → reduces RBF and GFR → worsens ischaemia. Also promotes mesangial contraction → reduces Kf. ETB RECEPTORS (two populations): (1) ETB on ENDOTHELIAL CELLS: releases NO and PGI2 → vasodilation (counterbalances ETA); endothelin clearance. (2) ETB on TUBULAR CELLS (collecting duct): inhibits ENaC and AQP2 → promotes natriuresis and aquaresis. Net effect in AKI: ET-1 rises markedly → predominantly ETA-mediated vasoconstriction → ischaemic injury. Selective ETA antagonists (ambrisentan, macitentan) studied in AKI — preserve ETB vasodilatory and natriuretic effects while blocking ischaemic vasoconstriction. Clinical trials ongoing for AKI prevention."]','A','ET-1 in AKI: ETA on VSM → vasoconstriction/ischaemia; ETB on endothelium → vasodilation/clearance; ETB on tubules → natriuresis. Selective ETA blockade is under study.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','easy','flashcard','State the clearance formula and explain what clearance means physiologically.','["Clearance formula: C = (U x V) / P, where U = urine concentration of substance (mg/mL or mEq/mL), V = urine flow rate (mL/min), P = plasma concentration. Units: mL/min. Physiological meaning: clearance is the VIRTUAL VOLUME of plasma completely cleared of a substance per minute. It is not a physical volume — no actual volume of plasma is completely cleared, but it is equivalent to what would be if all removal happened from a fraction of plasma. When clearance = GFR (125 mL/min), the substance is filtered only (like inulin). Clearance < GFR → net reabsorption. Clearance > GFR → net secretion (e.g., PAH clearance ~625 mL/min > GFR)."]','A','C = (U x V) / P; clearance is the virtual volume of plasma completely cleared per minute. C = GFR = filtered only; C < GFR = net reabsorption; C > GFR = net secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','easy','flashcard','Why is creatinine clearance used clinically instead of inulin clearance, and what are its limitations?','["Creatinine clearance is used because: (1) Endogenously produced at constant rate from muscle creatine phosphate; (2) No infusion required (unlike inulin); (3) Freely filtered at glomerulus; (4) Inexpensive to measure. LIMITATIONS: (1) Tubular secretion (~10-20% extra) → overestimates GFR by 10-20%; more significant in CKD; (2) Variable production (reduced in sarcopenia, cirrhosis, malnutrition → artificially low creatinine overestimates GFR; elevated in high meat diet → falsely elevated creatinine underestimates GFR); (3) 24-hour urine collection errors; (4) Drugs blocking secretion (cimetidine, trimethoprim) reduce creatinine clearance toward true GFR. Cystatin C-based equations (CKD-EPI 2021) now preferred for better accuracy across patient types."]','A','Creatinine clearance overestimates GFR 10-20% due to tubular secretion; production varies with muscle mass. Cystatin C equations are now preferred.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','How is effective renal plasma flow (ERPF) measured using PAH, and why is the result called ''effective'' RPF?','["ERPF measured by PAH clearance: ERPF = UPAH x V / PPAH (at low PAH concentrations where extraction ratio ~0.9). At low plasma [PAH], nearly all PAH in renal blood is cleared (filtered + secreted) per pass. CPAH = ERPF x 0.9 → ERPF = CPAH / 0.9. Called ''EFFECTIVE'' RPF because: (1) Not all renal blood passes through filtering nephrons (some supplies renal capsule, fat, etc.); (2) The extraction ratio is ~0.9, not 1.0, even at low concentrations (10% of blood bypasses secretory mechanisms). True RPF = ERPF / 0.9. Normal ERPF ~600-625 mL/min; true RPF ~650-700 mL/min. Above Tm, PAH secretion saturates → extraction ratio falls → PAH clearance no longer estimates RPF accurately."]','A','ERPF = CPAH / 0.9; called ''effective'' because 10% of renal blood bypasses active nephrons. Above Tm, PAH extraction falls, invalidating the measurement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','What is the concept of tubular transport maximum (Tm), and give examples of substances with defined Tm values?','["Transport maximum (Tm): the maximum rate at which tubular cells can transport a substance (via carrier-mediated transport). At filtered loads below Tm: all is reabsorbed (or all available is secreted). At loads above Tm: excess appears in urine (for reabsorptive Tm) or secretion rate plateaus (for secretory Tm). Examples with defined Tm: REABSORPTIVE: Glucose Tm ~375 mg/min (SGLT1+2 saturation → glucosuria above ~180 mg/dL plasma); Phosphate Tm (regulated by PTH and FGF23); Amino acids (various Tm per transporter). SECRETORY: PAH Tm ~80 mg/min (OAT1/3 saturation); Creatinine (modest Tm; always near saturation → secretion contributes 10-20% above filtration)."]','A','Tm = maximum carrier transport rate. Glucose Tm ~375 mg/min; PAH secretory Tm ~80 mg/min. Above Tm, excess spills into urine (reabsorptive) or secretion plateaus (secretory).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','Calculate GFR from the following data and state whether net secretion or reabsorption is occurring for substance X: Plasma inulin = 1 mg/mL, urine inulin = 125 mg/mL, urine flow = 1 mL/min; Plasma X = 2 mg/mL, urine X = 40 mg/mL.','["GFR = Cinulin = (125 x 1) / 1 = 125 mL/min. Clearance of X = (40 x 1) / 2 = 20 mL/min. Since CX (20) < GFR (125): NET REABSORPTION of X. Filtered load of X = GFR x plasma [X] = 125 x 2 = 250 mg/min. Excretion rate of X = 40 x 1 = 40 mg/min. Net reabsorption rate = 250 - 40 = 210 mg/min. Percentage reabsorbed = 210/250 = 84%. If CX were >125 mL/min, net secretion would be occurring. If CX = 125 mL/min, X would behave like inulin (filtered only, neither secreted nor reabsorbed)."]','A','GFR = 125 mL/min; CX = 20 mL/min < GFR → net reabsorption. 84% of filtered X is reabsorbed (210/250 mg/min).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','Explain free water clearance (CH2O) and what positive vs negative values mean.','["Free water clearance: CH2O = V - Cosm. Cosm = (Uosm x V) / Posm = osmolar clearance (mL/min of plasma cleared of all solutes). CH2O represents the volume of ''pure water'' being excreted above (positive) or below (negative) what would be needed for isosmotic urine. POSITIVE CH2O (''free water excretion''): Urine is dilute (Uosm < Posm); more water excreted than solutes require; ADH is low/absent; excess water is being eliminated (e.g., water loading). NEGATIVE CH2O (TcH2O — ''tubular conservation of water''): Urine is concentrated (Uosm > Posm); less water excreted than solutes would require; ADH is active; free water is being retained (appropriate in dehydration). Maximum negative CH2O (minimum urine flow) requires both high ADH and an intact medullary gradient."]','A','CH2O = V - Cosm. Positive = dilute urine (ADH absent, water excretion). Negative = concentrated urine (ADH active, water retained).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','What is the ''titration curve'' of PAH excretion as plasma PAH concentration is raised progressively?','["PAH titration curve: at LOW plasma [PAH] (<Tm): CPAH ≈ 0.9 x RPF (extraction ratio ~0.9) → PAH clearance is constant and high (~625 mL/min) → this is the useful range for measuring ERPF. As plasma [PAH] rises toward Tm (~80 mg/min secretory Tm): the secretory component becomes progressively saturated while filtration continues → extraction ratio falls. ABOVE Tm: PAH secretion is saturated; only filtration contributes → PAH clearance approaches GFR x 1 = 125 mL/min (if we ignore the secretory contribution). Urinary excretion rate above Tm rises linearly with filtered load only. This ''break'' in the PAH titration curve (extraction ratio changing from ~0.9 to ~0.2) illustrates both Tm for secretion and GFR in a single experiment."]','A','Below PAH Tm (~80 mg/min): clearance ~625 mL/min (measures ERPF). Above Tm: secretion saturates, clearance falls toward GFR (~125 mL/min).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','medium','flashcard','How does the GFR-creatinine relationship become problematic as GFR declines, and what does the ''creatinine blind spot'' mean?','["The GFR-creatinine relationship is inverse and NON-LINEAR (hyperbolic). At GFR 120 mL/min: creatinine ~0.8 mg/dL. At GFR 60 mL/min: creatinine ~1.6 mg/dL (doubled). At GFR 30 mL/min: creatinine ~3.2 mg/dL. At GFR 15 mL/min: creatinine ~6.4 mg/dL. THE ''CREATININE BLIND SPOT'': In the range GFR 60-120 mL/min, creatinine changes by only 0.4-0.8 mg/dL — often within normal range. A patient can lose 50% of GFR (120 → 60 mL/min) while creatinine only rises from 0.8 to 1.6 mg/dL (still ''normal'' in most labs). This means significant GFR loss is missed. Cystatin C is more sensitive in this range. GFR-estimating equations (CKD-EPI, MDRD) use age, sex, and race to improve precision."]','A','The hyperbolic GFR-creatinine curve means 50% GFR loss may only raise creatinine from 0.8 to 1.6 mg/dL (still ''normal'') — the creatinine blind spot; cystatin C is more sensitive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','hard','flashcard','Explain the splay in the glucose titration curve and how it differs from an ideal transporter.','["IDEAL transporter: all nephrons have identical Tm and glucose threshold; no glucosuria until filtered load exactly equals Tm; then every increment above Tm appears in urine → sharp ''threshold'' at ~300 mg/dL (plasma glucose where filtered load = Tm). REALITY (splay): individual nephrons have HETEROGENEOUS Tm values (Gaussian distribution around mean ~375 mg/min) AND heterogeneous SGLT2 affinity (Km). Nephrons with low Tm or low affinity begin spilling glucose before the population average Tm is reached. The titration curve shows a gradual slope (''splay'') rather than a sharp break. Practical result: glucosuria begins at ~180 mg/dL (renal threshold, where some nephrons saturate) even though average Tm corresponds to ~300 mg/dL. The area of splay represents nephron heterogeneity. SGLT2 inhibitors shift this curve by reducing Tm, causing glucosuria even at normal plasma glucose."]','A','Splay occurs because nephrons have heterogeneous Tm and SGLT2 affinity; glucosuria starts at ~180 mg/dL (some nephrons saturate) despite average Tm equivalent to ~300 mg/dL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Renal Clearance & Tubular Transport','hard','flashcard','What is the extraction ratio of PAH, how is it used to calculate RBF from ERPF, and what happens to it in severe CKD?','["Extraction ratio (ER) = (A - V) / A, where A = arterial [PAH] and V = renal venous [PAH]. Normal ER for PAH ≈ 0.9 (90% of incoming PAH is cleared per pass). ERPF = CPAH = PAH clearance (filtration + secretion). True RPF = ERPF / ER = CPAH / 0.9. Renal blood flow (RBF) = RPF / (1 - haematocrit) = 650 / (1 - 0.45) ≈ 1,180 mL/min. IN SEVERE CKD: (1) Remaining nephrons upregulate PAH secretion per nephron, partially compensating; (2) BUT total PAH secretory capacity falls as nephron number decreases; (3) Some studies show ER may decrease in CKD (reduced secretory capacity relative to filtered load), making CPAH a less reliable measure of RPF in advanced CKD. Additionally, accumulating organic anions compete with PAH for OAT1/3 → reduced PAH secretion even in remaining nephrons."]','A','ER = (A-V)/A ≈ 0.9 for PAH. RBF = ERPF / 0.9 / (1-Hct) ≈ 1180 mL/min. In severe CKD, ER falls (OAT1/3 competition, reduced nephron mass), invalidating CPAH as an RPF measure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','easy','flashcard','What is the normal plasma osmolality, how is it calculated, and what is the predominant determinant?','["Normal plasma osmolality: 285-295 mOsm/kg H2O (mean ~290). Formula: Posm ≈ 2[Na+] + glucose(mg/dL)/18 + BUN(mg/dL)/2.8. Alternatively: Posm ≈ 2[Na+] + glucose/18 + urea/2.8. PREDOMINANT DETERMINANT: Sodium and its accompanying anions (Cl-, HCO3-) account for ~270 of the 290 mOsm/kg (>90%). Glucose and urea each contribute ~5 mOsm/kg under normal conditions. Osmol gap = measured - calculated; normal <10 mOsm/kg; elevated gap suggests unmeasured osmoles (ethanol, methanol, ethylene glycol, mannitol). Osmolality is sensed by hypothalamic osmoreceptors that respond to as little as 1-2 mOsm/kg change to regulate ADH release and thirst."]','A','Normal Posm = 285-295 mOsm/kg. Formula: 2[Na+] + glucose/18 + BUN/2.8. Na+ and anions account for >90%. Osmol gap >10 suggests unmeasured osmoles.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','easy','flashcard','Where is ADH synthesised, where is it released, and what are the two types of stimuli for its secretion?','["SYNTHESIS: Magnocellular neurons in the supraoptic nucleus (SON) and paraventricular nucleus (PVN) of the hypothalamus. ADH is synthesised as part of prepro-vasopressin and processed during axonal transport. RELEASE: From axon terminals in the posterior pituitary (neurohypophysis) into the bloodstream. TWO CLASSES OF STIMULI: (1) OSMOTIC: plasma osmolality > 285 mOsm/kg → osmoreceptors in anterior hypothalamus (OVLT, SFO) → ADH release. Threshold ~285, steep response above ~295 mOsm/kg. (2) NON-OSMOTIC (override osmotic): volume/pressure signals — hypovolaemia (>10% volume loss), hypotension, nausea, hypoglycaemia, pain, some drugs (morphine, nicotine). These act via carotid/aortic baroreceptors → vagal afferents → hypothalamus → ADH; less sensitive but override osmotic inhibition."]','A','ADH synthesised in SON/PVN hypothalamus, released from posterior pituitary. Osmotic stimulus (>285 mOsm/kg) is primary; non-osmotic (hypovolaemia >10%) overrides at lower threshold.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','Explain the mechanism by which the kidney produces maximally dilute urine in the absence of ADH.','["Maximum dilution without ADH: (1) Tubular fluid enters the loop from the PCT at ~300 mOsm/kg. (2) Descending limb: water extracted (by hyperosmotic interstitium) → fluid concentrated to ~1200 mOsm/kg at papilla. (3) TAL: active NaCl pumped out (NKCC2), NO water follows → fluid diluted to ~100-150 mOsm/kg emerging into DCT. (4) DCT: further NaCl reabsorption (NCC), still water-impermeable → fluid falls to ~50-80 mOsm/kg. (5) Collecting duct: WITHOUT ADH, no AQP2 insertion → collecting duct is water-impermeable → dilute fluid (~50-70 mOsm/kg) passes through unchanged → excreted as very dilute urine. Maximum urine flow: up to 10-12 L/day (limited by GFR and upstream reabsorption). Minimum urine osmolality: ~50-70 mOsm/kg. The TAL''s NaCl-pumping without water movement is the key step in urinary dilution."]','A','The TAL pumps NaCl without water (NKCC2 + water-impermeability) diluting fluid to ~100 mOsm/kg; without ADH, the collecting duct remains impermeable → minimum urine ~50-70 mOsm/kg.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','What is SIADH? List four causes and describe the characteristic urine and plasma findings.','["SIADH (Syndrome of Inappropriate ADH secretion): ADH secreted despite normal/low plasma osmolality. CAUSES (four examples): (1) CNS: meningitis, subarachnoid haemorrhage, stroke, head injury; (2) Pulmonary: small cell lung cancer (ectopic ADH), pneumonia, TB, ARDS; (3) Drugs: SSRIs (most common drug cause), carbamazepine, cyclophosphamide, NSAIDs, chlorpropamide; (4) Idiopathic/physiological reset osmostat. CHARACTERISTIC FINDINGS: Plasma: low Na+ (<135 mEq/L), low osmolality (<280 mOsm/kg). Urine: inappropriately concentrated (Uosm >100 mOsm/kg, often >300); elevated urine Na+ (>40 mEq/L — because volume expansion suppresses aldosterone → Na+ not retained). Normal renal, adrenal, thyroid function. No oedema (volume distributed, not sequestered). Treatment: fluid restriction ± vaptans (V2 receptor antagonists → ''aquaresis'' without natriuresis) or hypertonic saline for symptomatic severe hyponatraemia."]','A','SIADH: low plasma Na+/Posm, inappropriately concentrated urine (Uosm >100), high urine Na+ (>40 mEq/L). Causes: CNS, lung cancer, SSRIs. Treat with fluid restriction ± vaptans.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','What is the water deprivation test and how does it differentiate central DI, nephrogenic DI, and primary polydipsia?','["Water deprivation test: patient deprived of water until urine osmolality plateaus OR serum osmolality > 295 mOsm/kg or >3% body weight loss. Then DDAVP (desmopressin, V2 agonist) is given. RESULTS: PRIMARY POLYDIPSIA: During deprivation, plasma osmolality rises (stops suppressing ADH) → urine concentrates to >750 mOsm/kg; DDAVP has minimal additional effect (kidneys already responding to endogenous ADH). CENTRAL DI: During deprivation, urine remains dilute (<300 mOsm/kg) despite rising plasma osmolality; AFTER DDAVP: urine osmolality rises >50% (kidneys intact — can respond to exogenous ADH). NEPHROGENIC DI: Same response to deprivation as central DI; AFTER DDAVP: urine osmolality does NOT rise significantly (<50% increase) because kidneys cannot respond to ADH."]','A','Water deprivation then DDAVP: polydipsia = concentrates during deprivation; central DI = dilute during deprivation, responds to DDAVP >50%; nephrogenic DI = dilute, no DDAVP response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','How do aquaporins 1, 2, 3, and 4 differ in their location and regulation in the kidney?','["AQP1: Constitutively expressed in PCT apical + basolateral membranes and descending thin limb. NOT regulated by ADH. Responsible for isosmotic PCT reabsorption and high water permeability of descending limb. AQP2: Collecting duct APICAL membrane only; stored in intracellular vesicles; REGULATED BY ADH (PKA-mediated phosphorylation → apical insertion). Long-term upregulated by ADH transcriptionally. The key regulated water channel. Mutations → nephrogenic DI. AQP3: Collecting duct BASOLATERAL membrane; constitutively expressed; provides exit path for water entering via AQP2. Also expressed in red blood cells. AQP4: Collecting duct basolateral membrane; constitutively expressed; also abundant in brain astrocytes and important in brain water balance/oedema."]','A','AQP1: PCT/descending limb, constitutive. AQP2: collecting duct apical, ADH-regulated (PKA→insertion), mutations→NDI. AQP3/4: collecting duct basolateral, constitutive exit channels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','How does lithium cause nephrogenic diabetes insipidus, and what is the rationale for treating it with amiloride?','["LITHIUM-INDUCED NDI mechanism: Li+ enters principal cells via ENaC (same size as Na+) → accumulates intracellularly because it is not a substrate for Na-K-ATPase. Intracellular Li+ inhibits: (1) Adenylyl cyclase → reduced cAMP production in response to ADH; (2) GSK-3 beta → disrupts AQP2 trafficking and expression. Chronic effect: downregulation of AQP2 mRNA and protein. Result: collecting duct cannot insert AQP2 → polyuria and polydipsia (NDI). AMILORIDE TREATMENT RATIONALE: Amiloride blocks ENaC → reduces Li+ entry into principal cells → less intracellular Li+ accumulation → partially preserves cAMP signalling and AQP2 expression → reduces polyuria. Additionally, amiloride reduces overall K+ wasting (Li+ also causes some kaliuresis). Thiazides (with low-Na diet) reduce proximal volume reabsorption → less flow to collecting duct → less urine output."]','A','Li+ enters via ENaC, inhibits adenylyl cyclase and GSK-3β → reduced AQP2 → NDI. Amiloride blocks ENaC, reducing Li+ entry and partially restoring AQP2.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','medium','flashcard','What is a reset osmostat, how does it differ from SIADH, and in which clinical settings does it occur?','["Reset osmostat: the osmotic threshold for ADH release and thirst is permanently reset to a LOWER SET POINT (e.g., 275 instead of 285 mOsm/kg). The ADH response above the new threshold is NORMAL (steepness preserved; kidney can still concentrate urine). DIFFERS FROM SIADH: In SIADH, ADH is secreted even as osmolality falls further below the threshold (no lower limit to secretion); kidney cannot dilute urine. In reset osmostat, the kidney CAN dilute urine below the new set point (water loading → urine dilution is normal relative to the new set point). CLINICAL SETTINGS: Pregnancy (normal physiological reset by relaxin — osmolality falls ~8 mOsm/kg to ~280); chronic malnutrition (reset from chronically low tonicity); quadriplegia (autonomic dysfunction); schizophrenia. The mild hyponatraemia of pregnancy (~132-136 mEq/L, stable) is NOT pathological — it represents normal reset."]','A','Reset osmostat: ADH threshold lowered but response is normal; urine CAN be diluted below the new set point. SIADH: ADH secreted with no lower threshold. Pregnancy is the classic example of reset osmostat.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','hard','flashcard','Explain why severe hyponatraemia causes cerebral oedema, and why rapid correction causes osmotic demyelination syndrome.','["CEREBRAL OEDEMA from hyponatraemia: Acute hyponatraemia → plasma osmolality falls → osmotic gradient drives water INTO brain cells → cell swelling → cerebral oedema → herniation risk. Brain compensates within hours by extruding organic osmolytes (taurine, glutamine, myoinositol) → brain volume returns toward normal → ''adapted'' to low osmolality. OSMOTIC DEMYELINATION (ODS) from rapid correction: If plasma Na+ is corrected too rapidly (>10-12 mEq/L/day), the plasma osmolality rises faster than the brain can restore its lost organic osmolytes (takes days) → brain cells shrink despite adequate neuron survival → oligodendrocyte death → demyelination of pons (central pontine myelinolysis) and extrapontine structures. Prevents correction: keep rate <10 mEq/L in 24 hours (<8 mEq/L in high-risk patients: alcoholism, malnutrition, hypokalaemia, liver disease)."]','A','Acute hyponatraemia → cerebral oedema (osmotic water influx). Brain adapts by extruding osmolytes; rapid correction shrinks the adapted brain → osmotic demyelination. Correct <10 mEq/L/day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Anatomy & Physiology','Water Balance & Osmolality','hard','flashcard','Explain the physiology of the ADH osmotic threshold — how ADH release changes with acute hypertonicity vs chronic dehydration.','["ADH secretion has a sigmoidal dose-response to plasma osmolality: BELOW threshold (~285 mOsm/kg): ADH is nearly undetectable; urine is maximally dilute (~50 mOsm/kg). AT threshold: ADH begins rising steeply — ~1 pg/mL per mOsm/kg rise. AT ~295-300 mOsm/kg: ADH ~5-10 pg/mL → urine >700 mOsm/kg (submaximal concentration). AT >300 mOsm/kg: ADH at maximum (~20-30 pg/mL) → urine ~1200 mOsm/kg. NON-OSMOTIC OVERRIDE: Volume depletion (>10% loss) shifts the threshold LEFTWARD and steepens the slope — ADH rises at lower osmolality (volume takes priority over osmolality in severe dehydration). CHRONIC DEHYDRATION: the threshold may reset slightly lower, and maximum achievable osmolality may fall (reduced medullary gradient due to reduced urea and protein malnutrition). Elderly patients have blunted thirst despite high osmolality → delayed drinking response → more severe dehydration."]','A','ADH rises steeply above ~285 mOsm/kg (sigmoid). Volume depletion >10% shifts threshold leftward. Chronic dehydration may reduce maximum concentrating ability; elderly have blunted thirst response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');
